function mountPuzzleBoards() { for (const p of state.training.puzzles) drawBoard($('#mini-' + p.id), p.fen, { orientation: p.color }); }
function openPuzzle(id) { const p = state.training.puzzles.find(p => p.id === id); if (!p) return; state.puzzle = { data: p, board: new Chess(p.fen), moves: [], selected: null, complete: false }; $('#puzzle-workspace').innerHTML = section('Найдите лучшее продолжение', `<div class="review"><div id="training-board"></div><div><h3>${p.color === 'w' ? 'Ход белых' : 'Ход чёрных'}</h3><p id="puzzle-feedback" class="method">Сделайте ход на доске. Соперник ответит автоматически.</p><div class="section-actions"><button class="button secondary" data-action="puzzle-hint">Подсказка</button><button class="button ghost" data-action="puzzle-solution">Показать решение</button><button class="button ghost" data-action="puzzle-reset">Начать заново</button></div><p>${linkGame(p.gameId, p.ply, 'Исходная партия')}</p><div id="puzzle-line" class="variation"></div></div></div>`); paintPuzzle(); $('#puzzle-workspace').scrollIntoView({ behavior: 'smooth', block: 'start' }); }
